#!/bin/bash
# launch of p2-c-pa-lt-t2_b1 on 3 lane(s): one queue per lane, 1 job each.  Usage: LAUNCH NODE0 [NODE1 [NODE2]]
# (default schrodinger for every lane; lane i runs on NODEi, or on the last node given).
# Run on einstein AFTER: preflight ok, a line in phase2_exploration/SLOTS.md, the approval (orchestrator launches).
# Resume after any stop: run this script again with the same nodes (complete campaigns and done jobs are skipped).
# Node cap per lane (jobs of this user on the node, this lane included): NODECAPS="3 3 4" in the environment,
# default 3 (a node with a graphical session); a lane waits while (other jobs + 1) exceeds its cap.
NODES=("$@"); [ ${#NODES[@]} -eq 0 ] && NODES=(schrodinger); CAPS=(${NODECAPS:-})
NODE=${NODES[0]:-${NODES[-1]}}; CAP=${CAPS[0]:-3}
echo "lane 0 on $NODE; qv2run jobs there now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pa-lt-t2-g4a-00; if [ -e /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane0.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane0.pid) 2>/dev/null; then echo lane 0 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane0.pid; NODECAP=$CAP exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4a-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-dif-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-nix-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4n-02.json' > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane0.log 2>&1 < /dev/null & echo lane 0 started; fi"
NODE=${NODES[1]:-${NODES[-1]}}; CAP=${CAPS[1]:-3}
echo "lane 1 on $NODE; qv2run jobs there now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pa-lt-t2-g4a-01; if [ -e /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane1.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane1.pid) 2>/dev/null; then echo lane 1 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane1.pid; NODECAP=$CAP exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4a-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-difc-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4n-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-dif-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni22-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni22-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni30-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni30-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni61-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-ni61-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-nic-00.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-nic-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-nix-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4l.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-lowpt.json' > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane1.log 2>&1 < /dev/null & echo lane 1 started; fi"
NODE=${NODES[2]:-${NODES[-1]}}; CAP=${CAPS[2]:-3}
echo "lane 2 on $NODE; qv2run jobs there now: $(ssh -x -o BatchMode=yes $NODE "pgrep -u jdochoa -af '[q]v2run job' | wc -l")"
ssh -x -o BatchMode=yes $NODE "mkdir -p /home/scratch/jdochoa/drivers; rm -f /home/scratch/jdochoa/drivers/STOP.p2-c-pa-lt-t2-g4a-02; if [ -e /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane2.pid ] && kill -0 \$(cat /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane2.pid) 2>/dev/null; then echo lane 2 already runs; else setsid nohup bash -c 'echo \$\$ > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane2.pid; NODECAP=$CAP exec /home/users/jdochoa/hllhc-quirks-search/analyses/quirks_v2/phase2_exploration/src/p2x_queue.sh $NODE 1 /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4a-02.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-difc-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4n-01.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-hph.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-g4h.json /home/users/jdochoa/hllhc-quirks-search/tools/runner/examples/p2x/launch_test_b1_t2/p2-c-pa-lt-t2-c0-hs.json' > /home/scratch/jdochoa/drivers/p2-c-pa-lt-t2_b1_3slots_lane2.log 2>&1 < /dev/null & echo lane 2 started; fi"
